#!/usr/bin/env node
// Generates an editor-agnostic .http request collection (VS Code REST Client /
// JetBrains HTTP Client) from the OpenAPI contract, grouped by tag, plus a
// multi-environment http-client.env.json. Regenerated by `task gen`; never edit
// the output by hand.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { parse } from "yaml";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = parse(readFileSync(join(root, "api/openapi.yaml"), "utf8"));
const outDir = join(root, "collections");
mkdirSync(outDir, { recursive: true });

const resolve = (node) => {
  if (node && typeof node === "object" && "$ref" in node) {
    const path = node.$ref.replace(/^#\//, "").split("/");
    let cur = spec;
    for (const p of path) cur = cur[p];
    return resolve(cur);
  }
  return node;
};

// Produce a minimal example JSON value for a schema (required props only where
// possible), using format-aware placeholders.
const example = (schemaRaw) => {
  const schema = resolve(schemaRaw);
  if (!schema) return null;
  if (schema.example !== undefined) return schema.example;
  if (schema.default !== undefined) return schema.default;
  if (schema.enum) return schema.enum[0];
  switch (schema.type) {
    case "object": {
      const out = {};
      const props = schema.properties ?? {};
      const required = schema.required ?? Object.keys(props);
      for (const key of Object.keys(props)) {
        if (required.includes(key)) out[key] = example(props[key]);
      }
      return out;
    }
    case "array":
      return [example(schema.items)];
    case "integer":
    case "number":
      return schema.minimum ?? 1;
    case "boolean":
      return true;
    case "string":
      switch (schema.format) {
        case "uuid":
          return "00000000-0000-0000-0000-000000000000";
        case "date":
          return "2026-01-01";
        case "date-time":
          return "2026-01-01T00:00:00Z";
        case "uri-reference":
          return "/example";
        default:
          return "string";
      }
    default:
      return null;
  }
};

const base = (spec.servers?.[0]?.url ?? "").replace(/^https?:\/\/[^/]+/, "");
const groups = new Map();

for (const [path, item] of Object.entries(spec.paths)) {
  const pathParams = item.parameters ?? [];
  for (const method of ["get", "post", "put", "patch", "delete"]) {
    const op = item[method];
    if (!op) continue;
    const tag = op.tags?.[0] ?? "default";
    const params = [...pathParams, ...(op.parameters ?? [])].map(resolve);

    // Build URL with path params as {{var}} and query params appended.
    // Substitute path params on the path segment only, then prefix baseUrl so
    // the {{baseUrl}} braces are not re-wrapped.
    const pathWithVars = path.replace(/\{([^}]+)\}/g, (_, p) => `{{${p}}}`);
    let url = `{{baseUrl}}${pathWithVars}`;
    const query = params
      .filter((p) => p.in === "query")
      .map((p) => `${p.name}=${p.schema?.default ?? `{{${p.name}}}`}`);
    if (query.length) url += `?${query.join("&")}`;

    const lines = [];
    lines.push(`### ${op.operationId} — ${op.summary ?? ""}`.trim());
    lines.push(`${method.toUpperCase()} ${url}`);

    const secured = (op.security ?? spec.security ?? []).length > 0;
    if (secured) {
      lines.push("Authorization: Bearer {{token}}");
      lines.push("x-api-key: {{apiKey}}");
    }
    for (const p of params.filter((p) => p.in === "header")) {
      lines.push(`${p.name}: {{${p.name.replace(/-/g, "_")}}}`);
    }

    const body = op.requestBody && resolve(op.requestBody);
    const jsonSchema = body?.content?.["application/json"]?.schema;
    if (jsonSchema) {
      lines.push("Content-Type: application/json");
      lines.push("");
      lines.push(JSON.stringify(example(jsonSchema), null, 2));
    }

    if (!groups.has(tag)) groups.set(tag, []);
    groups.get(tag).push(lines.join("\n"));
  }
}

for (const [tag, blocks] of groups) {
  const header = `# ${tag} requests — generated from api/openapi.yaml by task gen. Do not edit.\n# Select an environment (local/dev/staging/prod) in http-client.env.json.\n\n`;
  writeFileSync(join(outDir, `${tag}.http`), header + blocks.join("\n\n") + "\n");
}

// Multi-environment variables. Non-secret defaults only; tokens are populated
// by `task token`. baseUrl already includes the server's /v1 base path.
const env = {
  local: { baseUrl: `http://localhost:3000${base}`, apiKey: "local-dev-key", token: "" },
  dev: { baseUrl: `https://dev.api.example.com${base}`, apiKey: "", token: "" },
  staging: { baseUrl: `https://staging.api.example.com${base}`, apiKey: "", token: "" },
  prod: { baseUrl: `https://api.example.com${base}`, apiKey: "", token: "" },
};
writeFileSync(join(outDir, "http-client.env.json"), JSON.stringify(env, null, 2) + "\n");

console.log(`Generated ${groups.size} .http file(s) + http-client.env.json in collections/`);
